    /**
     * Handles loading a Quote using a UUID
     * @param		UUID uuid 
     * @return		Quote
     */    
    @GetMapping("/load")
    public Quote load( @RequestParam(required=true) UUID uuid ) {    	
    	Quote entity = null;

    	try {  
    		entity = service.getQuote( new QuoteFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Quote using Id " + uuid );
            return null;
        }

        return entity;
    }

